-- THQ ERP v5.2 GST & Compliance
-- Migration 234: guarded authoritative GST document journal poster.
begin;
create or replace function private.gst_journal_matches_expected_v520(p_tenant_id uuid,p_journal_id uuid,p_expected jsonb) returns boolean language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare v_mismatch int;v_zero int;v_generic int;begin if not exists(select 1 from public.journal_entries j where j.id=p_journal_id and j.tenant_id=p_tenant_id and j.status='posted') then return false;end if;with expected as (select (x->>'account_id')::uuid account_id,nullif(x->>'party_type','') party_type,nullif(x->>'party_id','')::uuid party_id,round(sum(coalesce((x->>'debit')::numeric,0)),2) debit,round(sum(coalesce((x->>'credit')::numeric,0)),2) credit from jsonb_array_elements(coalesce(p_expected,'[]'::jsonb)) x group by 1,2,3),actual as (select l.account_id,l.party_type,l.party_id,round(sum(l.debit),2) debit,round(sum(l.credit),2) credit from public.journal_lines l where l.journal_entry_id=p_journal_id group by 1,2,3),cmp as (select coalesce(e.account_id,a.account_id) account_id,coalesce(e.party_type,a.party_type) party_type,coalesce(e.party_id,a.party_id) party_id,coalesce(e.debit,0) e_dr,coalesce(e.credit,0) e_cr,coalesce(a.debit,0) a_dr,coalesce(a.credit,0) a_cr from expected e full join actual a on a.account_id=e.account_id and a.party_type is not distinct from e.party_type and a.party_id is not distinct from e.party_id) select count(*) into v_mismatch from cmp where abs(e_dr-a_dr)>0.005 or abs(e_cr-a_cr)>0.005;select count(*) into v_zero from public.journal_lines where journal_entry_id=p_journal_id and round(debit,2)=0 and round(credit,2)=0;select count(*) into v_generic from public.journal_lines l join public.accounting_accounts a on a.id=l.account_id where l.journal_entry_id=p_journal_id and a.system_key in('input_gst','output_gst');return v_mismatch=0 and v_zero=0 and v_generic=0;end $$;
revoke all on function private.gst_journal_matches_expected_v520(uuid,uuid,jsonb) from public,anon,authenticated;
create or replace function private.gst_authoritative_journal_post_v520(p_tenant_id uuid,p_snapshot_id uuid) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$declare s public.gst_document_snapshots_v520%rowtype;v_expected jsonb;v_validation jsonb;v_existing uuid;v_created uuid;v_desc text;begin select * into s from public.gst_document_snapshots_v520 where id=p_snapshot_id and tenant_id=p_tenant_id;if not found then raise exception 'Authoritative GST snapshot not found';end if;if exists(select 1 from public.gst_legacy_document_markers_v520 m where m.tenant_id=p_tenant_id and m.source_type=s.source_type and m.source_id=s.source_id) then raise exception 'Legacy-unverified GST evidence cannot be posted as authoritative component accounting';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||s.source_type||':'||s.source_id::text,0));v_validation:=private.gst_snapshot_document_journal_validate_v520(p_tenant_id,p_snapshot_id);v_expected:=v_validation->'lines';select j.id into v_existing from public.journal_entries j where j.tenant_id=p_tenant_id and j.source_type=s.source_type and j.source_id=s.source_id and j.status='posted' order by j.created_at limit 1;if v_existing is not null then if private.gst_journal_matches_expected_v520(p_tenant_id,v_existing,v_expected) then return v_existing;end if;raise exception 'A posted journal already exists for this GST source but does not match the authoritative GST snapshot';end if;v_desc:=case s.source_type when 'sale' then 'GST Sale ' when 'purchase' then 'GST Purchase ' when 'purchase_invoice_v484' then 'GST Purchase Invoice ' when 'sales_return' then 'GST Sales Return ' when 'purchase_return' then 'GST Purchase Return ' else 'GST Document ' end||s.source_number;v_created:=private.v4_journal_create(p_tenant_id,s.location_id,s.document_date,v_desc,s.source_type,s.source_id,s.source_number,v_expected);if v_created is null or not private.gst_journal_matches_expected_v520(p_tenant_id,v_created,v_expected) then raise exception 'Posted GST journal failed authoritative snapshot verification';end if;return v_created;end $$;
revoke all on function private.gst_authoritative_journal_post_v520(uuid,uuid) from public,anon,authenticated;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(234,'5.2.0-foundation','Authoritative GST Journal Poster','Adds the private guarded component-journal poster. It requires immutable authoritative GST evidence, refuses legacy evidence, serializes by source, verifies exact aggregated journal lines, rejects generic Input/Output GST controls and makes matching retries idempotent. No app endpoint is switched.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;
commit;